package cloudflarewarp_test

import (
	"context"
	"net/http"
	"net/http/httptest"
	"strconv"
	"testing"

	plugin "github.com/BetterCorp/cloudflarewarp"
)

func TestNew(t *testing.T) {
	cfg := plugin.CreateConfig()
	cfg.TrustIP = []string{"103.21.244.0/22", "172.18.0.1/32", "2405:b500::/32"}

	ctx := context.Background()
	next := http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {})
	handler, err := plugin.New(ctx, next, cfg, "cloudflarewarp")
	if err != nil {
		t.Fatal(err)
	}
	testCases := []struct {
		ipv6           bool
		expect400      bool
		trusted        bool
		remote         string
		desc           string
		cfConnectingIP string
		cfVisitor      string
		expected       string
		expectedScheme string
	}{
		{
			remote:         "103.21.244.23",
			desc:           "blank scheme",
			cfConnectingIP: "10.0.0.1",
			cfVisitor:      "",
			expected:       "10.0.0.1",
			expectedScheme: "",
			trusted:        true,
		},
		{
			remote:         "103.21.244.23",
			desc:           "https scheme",
			cfConnectingIP: "10.0.0.1",
			cfVisitor:      "{\"scheme\":\"https\"}",
			expected:       "10.0.0.1",
			expectedScheme: "https",
			trusted:        true,
		},
		{
			remote:         "10.0.1.20",
			desc:           "not trust",
			cfConnectingIP: "127.0.0.2",
			cfVisitor:      "",
			expected:       "",
			expectedScheme: "",
			trusted:        false,
		},
		{
			remote:         "10.0.1.20",
			desc:           "not trust ip4/6",
			cfConnectingIP: "1001:3984:3989::1",
			cfVisitor:      "",
			expected:       "",
			expectedScheme: "",
			trusted:        false,
		},
		{
			remote:         "1001:3984:3989::1",
			ipv6:           true,
			desc:           "not trust ip6/6",
			cfConnectingIP: "1001:3984:3989::1",
			cfVisitor:      "",
			expected:       "",
			expectedScheme: "",
			trusted:        false,
		},
		{
			remote:         "1001:3984:3989::1",
			ipv6:           true,
			desc:           "not trust ip6/4",
			cfConnectingIP: "10.0.1.20",
			cfVisitor:      "",
			expected:       "",
			expectedScheme: "",
			trusted:        false,
		},
		{
			remote:         "10.0.2",
			desc:           "wrong IP format",
			cfConnectingIP: "10.0.0.1",
			cfVisitor:      "",
			expected:       "",
			expectedScheme: "",
			expect400:      true,
			trusted:        false,
		},
		{
			remote:         "10.0.300.20",
			desc:           "wrong IP address",
			cfConnectingIP: "10.0.0.1",
			cfVisitor:      "",
			expected:       "",
			expectedScheme: "",
			expect400:      true,
			trusted:        false,
		},
		{
			remote:         "103.21.244.23",
			desc:           "forward",
			cfConnectingIP: "10.0.0.1",
			cfVisitor:      "",
			expected:       "10.0.0.1",
			expectedScheme: "",
			trusted:        true,
		},
		{
			remote:         "172.18.0.1",
			desc:           "forward",
			cfConnectingIP: "10.0.0.1",
			cfVisitor:      "",
			expected:       "10.0.0.1",
			expectedScheme: "",
			trusted:        true,
		},
	}
	for _, test := range testCases {
		test := test
		t.Run(test.desc, func(t *testing.T) {
			recorder := httptest.NewRecorder()

			req, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://localhost", nil)
			if err != nil {
				t.Fatal(err)
			}
			if test.ipv6 == true {
				req.RemoteAddr = "[" + test.remote + "]:36001"
			} else {
				req.RemoteAddr = test.remote + ":36001"
			}
			req.Header.Set("X-Real-Ip", test.remote)
			req.Header.Set("Cf-Connecting-IP", test.cfConnectingIP)
			req.Header.Set("Cf-Visitor", test.cfVisitor)

			handler.ServeHTTP(recorder, req)

			if recorder.Result().StatusCode == http.StatusBadRequest {
				if test.expect400 == true {
					return
				}
			}
			if recorder.Result().StatusCode != http.StatusOK {
				t.Errorf("invalid response: " + strconv.Itoa(recorder.Result().StatusCode))
				return
			}

			if test.trusted {
				assertHeader(t, req, "X-Is-Trusted", "yes")
				assertHeader(t, req, "X-Real-Ip", test.expected)
			} else {
				assertHeader(t, req, "X-Is-Trusted", "no")
				assertHeader(t, req, "X-Real-Ip", test.remote)
			}
			assertHeader(t, req, "X-Forwarded-For", test.expected)
			assertHeader(t, req, "X-Forwarded-Proto", test.expectedScheme)
		})
	}
}

func TestError(t *testing.T) {
	cfg := plugin.CreateConfig()
	cfg.TrustIP = []string{"103.21.244.0"}

	ctx := context.Background()
	next := http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {})
	_, err := plugin.New(ctx, next, cfg, "cloudflarewarp")
	if err == nil {
		t.Fatalf("expected error, got none")
	}
}

func assertHeader(t *testing.T, req *http.Request, key, expected string) {
	t.Helper()

	if req.Header.Get(key) != expected {
		t.Errorf("invalid header(%s) value: %s", key, req.Header.Get(key))
	}
}

#!/bin/sh

echo "";
echo "";
echo "*** STARTING TEST FOR : ${1}-${2}-${3}";
echo "";
echo "";

rm -rf ./logs;
rm -rf ./tempconfig;

mkdir ./logs;
mkdir ./tempconfig;

touch ./logs/access.log;
touch ./logs/debug.log;
touch ./logs/traefik.log;
touch ./logs/output.log;

cp "./config/${1}.${2}" "./tempconfig/config.${2}"

chmod -R 7777 ./logs;
chmod -R 7777 ./tempconfig;

sleep 2s;

if [ "${3}" = "stack" ]; then
  docker stack deploy -c docker-stack.yml test-instance;
  sleep 1s;
else
  docker-compose up -d;
  sleep 1s;
fi

iterations=0
while ! grep -q "Starting TCP Server" "./logs/debug.log" && [ $iterations -lt 30 ]; do
  sleep 1s
  echo "Waiting for Traefik to be ready [${iterations}s/30]"
  let iterations++
done

iterations=0
while ! grep -q "Provider connection established with docker" "./logs/debug.log" && [ $iterations -lt 30 ]; do
  sleep 1s
  echo "Waiting for Traefik to connect to docker [${iterations}s/30]"
  let iterations++
done

iterations=0
while ! grep -q "Propagating new UP status" "./logs/debug.log" && [ $iterations -lt 30 ]; do
  sleep 1s
  echo "Waiting for Traefik to UP the service [${iterations}s/30]"
  let iterations++
done

curl -H "CF-Connecting-IP:${4}" -H "CF-Visitor:{\"scheme\":\"https\"}" http://localhost:4008/ >> ./logs/output.log;
echo "Headers:\nCF-Connecting-IP:${4}\nCF-Visitor:{\"scheme\":\"https\"}" >> ./logs/request.log
cat ./logs/output.log;

if [ "${3}" = "stack" ] ; then
  docker stack rm test-instance;
  sleep 1s;
else
  sleep 1s;
  docker-compose down;
fi
